class GameStatus{checkAll(){var n=$("#status-all").prop("checked"),t=$("#status-tbl");t.find(".game-status-chk").prop({checked:n})}uncheckAll(n){$(n).is(":checked")||$("#status-all").prop({checked:!1})}enable(){var n=this.getCheckedGames(),t,i;n.message.length>0?(t="ENABLE games:\n"+n.message+"Are you sure?",i=$("#reload").is(":checked"),confirm(t)&&$.ajax({method:"POST",url:"/status/enable",data:{games:n.games,reload:i}}).done(function(n){n&&(window.location.href="/status")})):alert("You should choose at least one game.")}disable(){var n=this.getCheckedGames(),t,i;n.message.length>0?(t="DISABLE games:\n"+n.message+"Are you sure?",i=$("#reload").is(":checked"),confirm(t)&&$.ajax({method:"POST",url:"/status/disable",data:{games:n.games,reload:i}}).done(function(n){n&&(window.location.href="/status")})):alert("You should choose at least one game.")}getCheckedGames(){for(var u,f,e=$("#status-tbl"),t=e.find(".game-status-chk"),i="",r=[],n=0;n<t.length;n++)$(t[n]).is(":checked")&&(r.push($(t[n]).val()),u=$(t[n]).parent(),f=u.find(".game-display-name"),i+="- "+f.val()+"\n");return{games:r,message:i}}showForm(n){var t=$(n).parent(),i=$(t).parent().find(".form-disabled-message");i.show();t.hide()}}var gameStatus=new GameStatus;